请对以下 case 进行三维加权评分。

=== case_id ===
Case-06-memory-clean-003

=== 用户原始指令 (query.txt) ===
内存卡点进应用，红字提醒我快满了啊

=== TaskSpec 契约 (task.taskSpec.json) ===
{
  "userQuery": "内存卡点进应用，红字提醒我快满了啊",
  "size": "2x2",
  "eventCandidates": [
    {
      "call": "clickToDeeplink",
      "args": {
        "bundleName": "com.huawei.hmos.settings",
        "abilityName": "com.huawei.hmos.settings.MainAbility",
        "uri": "storage_settings"
      }
    }
  ],
  "dataModelSchema": {
    "memory": {
      "title": {
        "type": "string",
        "description": "内存清理卡片的服务对象标题。",
        "sampleValue": "手机内存"
      },
      "statusText": {
        "type": "string",
        "description": "当前内存状态提醒文案，需要突出快满告警。",
        "sampleValue": "快满了"
      },
      "usedText": {
        "type": "string",
        "description": "当前内存已使用比例展示文本。",
        "sampleValue": "已用 92%"
      },
      "freeText": {
        "type": "string",
        "description": "当前剩余可用内存展示文本。",
        "sampleValue": "剩余 8GB"
      }
    },
    "action": {
      "label": {
        "type": "string",
        "description": "进入存储空间清理入口的短按钮文案。",
        "sampleValue": "去清理"
      }
    }
  },
  "assetCandidates": [
    {
      "src": "resources/base/media/icon_clear.png",
      "description": "清除图标，适合表达清理无忧、内存释放或垃圾清理入口。"
    }
  ]
}

